module longest_subsegment (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    input [3:0] len,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State parameters\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] CAPTURE        = 4'd1;\n    localparam [3:0] COMPUTE_LEFT   = 4'd2;\n    localparam [3:0] COMPUTE_RIGHT  = 4'd3;\n    localparam [3:0] COMPUTE_ANSWER = 4'd4;\n    localparam [3:0] DONE_STATE     = 4'd5;\n    \n    // Internal storage\n    reg [7:0] arr_reg [0:7];\n    reg [3:0] left [0:7];\n    reg [3:0] right [0:7];\n    reg [7:0] ans;\n    reg [3:0] state;\n    reg [3:0] i;\n    reg [3:0] len_reg;\n    integer k;  // Initialize arrays in reset\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            ans <= 8'd0;\n            i <= 4'd0;\n            len_reg <= 4'd0;\n            \n            // Initialize all array elements\n            for (k = 0; k < 8; k = k + 1) begin\n                arr_reg[k] <= 8'd0;\n                left[k] <= 4'd0;\n                right[k] <= 4'd0;\n            end\n        \n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= CAPTURE;\n                        i <= 4'd0;\n                        ans <= 8'd0;\n                        len_reg <= (len > 4'd8) ? 4'd8 : len;\n                    end\n                end\n                \n                CAPTURE: begin\n                    if (i < len_reg) begin\n                        case (i)\n                            4'd0: arr_reg[0] <= arr_0;\n                            4'd1: arr_reg[1] <= arr_1;\n                            4'd2: arr_reg[2] <= arr_2;\n                            4'd3: arr_reg[3] <= arr_3;\n                            4'd4: arr_reg[4] <= arr_4;\n                            4'd5: arr_reg[5] <= arr_5;\n                            4'd6: arr_reg[6] <= arr_6;\n                            4'd7: arr_reg[7] <= arr_7;\n                        endcase\n                        i <= i + 4'd1;\n                    end else begin\n                        i <= 4'd0;\n                        state <= (len_reg > 4'd0) ? COMPUTE_LEFT : DONE_STATE;\n                    end\n                end\n                \n                COMPUTE_LEFT: begin\n                    if (i < len_reg) begin\n                        if (i == 4'd0) begin\n                            left[0] <= 4'd1;\n                            if (4'd1 > ans) ans <= 4'd1;\n                        end else begin\n                            if (arr_reg[i] > arr_reg[i-1]) begin\n                                left[i] <= left[i-1] + 4'd1;\n                                if ((left[i-1] + 4'd1) > ans) ans <= left[i-1] + 4'd1;\n                            end else begin\n                                left[i] <= 4'd1;\n                                if (4'd1 > ans) ans <= 4'd1;\n                            end\n                        end\n                        i <= i + 4'd1;\n                    end else begin\n                        i <= len_reg - 4'd1;\n                        state <= COMPUTE_RIGHT;\n                    end\n                end\n                \n                COMPUTE_RIGHT: begin\n                    if (i >= 0 && i < len_reg) begin\n                        if (i == len_reg - 4'd1) begin\n                            right[i] <= 4'd1;\n                        end else begin\n                            if (arr_reg[i] < arr_reg[i+1]) begin\n                                right[i] <= right[i+1] + 4'd1;\n                            end else begin\n                                right[i] <= 4'd1;\n                            end\n                        end\n                        if (i == 4'd0) begin\n                            i <= len_reg;\n                        end else begin\n                            i <= i - 4'd1;\n                        end\n                    end else begin\n                        i <= 4'd0;\n                        state <= COMPUTE_ANSWER;\n                    end\n                end\n                \n                COMPUTE_ANSWER: begin\n                    if (i < len_reg) begin\n                        if (i > 4'd0) begin\n                            if (left[i-1] + 4'd1 > ans) ans <= left[i-1] + 4'd1;\n                        end\n                        if (i < len_reg - 4'd1) begin\n                            if (right[i+1] + 4'd1 > ans) ans <= right[i+1] + 4'd1;\n                        end\n                        if (i > 4'd0 && i < len_reg - 4'd1) begin\n                            if (arr_reg[i-1] + 8'd1 < arr_reg[i+1]) begin\n                                if ((left[i-1] + right[i+1] + 4'd1) > ans) begin\n                                    ans <= left[i-1] + right[i+1] + 4'd1;\n                                end\n                            end\n                        end\n                        i <= i + 4'd1;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    result <= ans;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule